@import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@400;500;600;700;800&family=DM+Sans:wght@400;500;600;700&display=swap');
:root{--ink:#100d18;--gold:#e4b66e;--gold2:#f4d49b;--cream:#f6ead1;--muted:#a69a9a;--red:#df665d;--line:rgba(226,188,128,.27)}*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--ink);color:var(--cream);font-family:'DM Sans',sans-serif}button{font:inherit;color:inherit}#game-shell{position:relative;width:100vw;height:100dvh;min-height:520px;overflow:hidden;background:#17121d}canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette,.grain{position:absolute;inset:0;pointer-events:none}.vignette{background:radial-gradient(ellipse at 50% 48%,transparent 34%,rgba(9,7,13,.22) 75%,rgba(9,7,13,.72) 130%)}.grain{opacity:.07;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.5'/%3E%3C/svg%3E")}.topbar{position:absolute;z-index:4;top:0;left:0;right:0;height:80px;padding:0 5.3%;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(226,188,128,.14);background:linear-gradient(180deg,rgba(13,10,17,.75),transparent)}.brand{display:flex;align-items:center;gap:12px}.brand-mark{font-size:26px;color:var(--gold);text-shadow:0 0 18px #e4b66e80}.brand b,.brand small{display:block;font-family:Cinzel,serif;letter-spacing:.16em}.brand b{font-size:13px;font-weight:700}.brand small{margin-top:3px;color:#a89c95;font-size:8px;letter-spacing:.29em}.room-label{font-family:Cinzel,serif;font-size:10px;letter-spacing:.22em;color:#d4c3a9;display:flex;align-items:center;gap:10px}.live-dot{width:5px;height:5px;border-radius:50%;background:#df735e;box-shadow:0 0 10px #df735e}.icon-btn{width:34px;height:34px;border:1px solid #dfc18d40;background:#17121d88;color:var(--gold);border-radius:50%;font-size:15px;cursor:pointer}.hud{position:absolute;z-index:3;top:100px;left:5.3%;right:5.3%;display:flex;align-items:flex-start;justify-content:space-between;pointer-events:none}.hidden{display:none!important}.health-wrap{width:205px}.health-head{display:flex;justify-content:space-between;color:#c6b7a5;font:10px Cinzel,serif;letter-spacing:.13em}.health-head b{color:#f4dfbb;font-weight:500;letter-spacing:.04em}.health-track{height:5px;margin-top:8px;background:#1a141f;border:1px solid #d5bd8433;transform:skewX(-18deg)}.health-track i{display:block;width:100%;height:100%;background:linear-gradient(90deg,#bd514c,#ed9070);box-shadow:0 0 10px #c9515180;transition:width .25s}.heart-row{display:flex;gap:5px;margin-top:8px}.heart-row span{width:5px;height:5px;background:#e37a69;transform:rotate(45deg);box-shadow:0 0 5px #e37a6950}.wave-wrap{position:absolute;left:50%;top:-1px;transform:translateX(-50%);text-align:center;min-width:170px}.wave-wrap span,.wave-wrap small{display:block;color:#a99b97;font:9px Cinzel,serif;letter-spacing:.2em}.wave-wrap strong{display:block;color:var(--gold2);font:500 27px Cinzel,serif;line-height:1.18}.wave-wrap small{margin-top:3px;font-size:8px;letter-spacing:.14em}.right-hud{text-align:right}.boon-tag{display:flex;align-items:center;gap:9px;text-align:left;justify-content:flex-end;color:var(--gold)}.boon-tag>span{font-size:22px}.boon-tag small,.boon-tag b{display:block;font:8px Cinzel,serif;letter-spacing:.13em}.boon-tag small{color:#b4a39a;font-size:7px}.boon-tag b{margin-top:3px;color:#f4dfbb;font-size:10px}.dash-pips{margin-top:11px;display:flex;justify-content:flex-end;gap:4px}.dash-pips i{width:17px;height:3px;background:#e6bc76;box-shadow:0 0 7px #e6bc7660}.dash-pips i.off{background:#60535a;box-shadow:none}.screen{position:absolute;z-index:5;inset:0;display:flex;flex-direction:column;justify-content:center;align-items:center;background:linear-gradient(90deg,rgba(13,10,18,.9) 0%,rgba(15,11,19,.78) 44%,rgba(16,12,20,.19) 100%);animation:fade .5s ease both}.screen.visible{display:flex}.intro-copy{position:absolute;left:10%;top:20%;width:min(450px,38vw)}.eyebrow{display:flex;align-items:center;gap:10px;color:var(--gold);font:9px Cinzel,serif;letter-spacing:.22em}.eyebrow i{width:20px;height:1px;background:var(--gold);opacity:.7}.intro-copy h1,.modal-card h2{margin:22px 0 14px;font:500 clamp(43px,5.3vw,75px)/.99 Cinzel,serif;letter-spacing:.015em;text-shadow:0 6px 25px #0a0710}.intro-copy h1 em,.modal-card h2 em{font-style:normal;color:var(--gold2)}.intro-copy p{color:#c3b9b3;font-size:13px;line-height:1.8;letter-spacing:.025em}.controls-note{margin-top:24px;color:#9e9290;font:8px Cinzel,serif;letter-spacing:.12em}.controls-note span{padding:4px 6px;border:1px solid #d8c1944c;color:#eed7ad;margin-right:4px}.controls-note b{margin:0 7px;color:var(--gold)}.weapon-section{position:absolute;left:53%;right:9%;top:24%;max-width:570px}.select-heading{display:flex;gap:14px;align-items:center;color:#e2c99e;font:9px Cinzel,serif;letter-spacing:.2em;margin-bottom:14px}.select-heading i{height:1px;flex:1;background:linear-gradient(90deg,#d9ba814c,transparent)}.weapon-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.weapon-card{position:relative;min-width:0;height:222px;text-align:left;padding:13px 12px 12px;background:linear-gradient(145deg,rgba(38,30,39,.91),rgba(22,17,27,.91));border:1px solid rgba(214,190,145,.23);cursor:pointer;transition:transform .2s,border .2s,background .2s;overflow:hidden}.weapon-card:before{content:'';position:absolute;inset:0;background:radial-gradient(ellipse at 50% 25%,#d1a96c12,transparent 65%);pointer-events:none}.weapon-card:hover{transform:translateY(-3px);border-color:#e4b66e9c}.weapon-card.selected{border-color:var(--gold);box-shadow:inset 0 0 18px #e4b66e12,0 0 22px #e4b66e10}.weapon-index{position:absolute;right:12px;top:12px;color:#a99b87;font:10px Cinzel,serif}.weapon-art{display:block;height:84px;text-align:center;padding-top:5px;color:#ecc57f;font-size:56px;line-height:1;text-shadow:0 0 25px #e6b95a75}.blade-art{color:#ef8c72;text-shadow:0 0 25px #e37c6475}.bow-art{font-size:66px;color:#9eb8b3;text-shadow:0 0 25px #8dc5b875}.weapon-name{display:block;color:#f0dfc2;font:600 10px Cinzel,serif;letter-spacing:.1em;white-space:nowrap}.weapon-desc{display:block;margin-top:5px;color:#9e9290;font-size:9px;white-space:nowrap}.weapon-stats{display:grid;grid-template-columns:1fr auto;align-items:center;gap:3px 7px;margin-top:12px}.weapon-stats i{display:block;height:2px;width:100%;background:linear-gradient(90deg,#dcaf6c var(--stat),#554a4b var(--stat))}.weapon-stats small{color:#938983;font:7px Cinzel,serif;letter-spacing:.1em}.weapon-pick{position:absolute;right:10px;bottom:10px;color:#9b8e86;font:7px Cinzel,serif;letter-spacing:.14em}.weapon-card.selected .weapon-pick{color:var(--gold)}.begin-btn{display:flex;align-items:center;justify-content:space-between;width:100%;height:45px;padding:0 17px;border:1px solid #e4b66e;background:linear-gradient(100deg,#b37b44,#d6a960);color:#1b1319;font:700 10px Cinzel,serif;letter-spacing:.16em;cursor:pointer;box-shadow:0 5px 22px #c28f4840;transition:filter .2s,transform .2s}.begin-btn:hover{filter:brightness(1.13);transform:translateY(-1px)}.begin-btn span{font-size:17px}.weapon-section>.begin-btn{margin-top:13px}.screen-foot{position:absolute;bottom:27px;left:5.3%;right:5.3%;display:flex;justify-content:space-between;color:#8f8384;font:8px Cinzel,serif;letter-spacing:.15em}.modal{background:rgba(12,9,16,.72);backdrop-filter:blur(5px)}.modal-card{width:min(390px,88vw);padding:36px 38px;background:linear-gradient(145deg,#241c27f5,#17121df5);border:1px solid #d6b87a57;box-shadow:0 20px 80px #08060ca8;text-align:center}.modal-card .eyebrow{justify-content:center}.modal-card h2{font-size:45px;margin:20px 0 10px}.modal-card p{color:#b5a9a5;font-size:12px;margin:0 0 24px}.text-btn{margin-top:17px;background:none;border:0;color:#9c8d8c;font:8px Cinzel,serif;letter-spacing:.15em;cursor:pointer}.run-stats{display:flex;justify-content:center;gap:30px;margin:20px 0 24px;color:#a59794;font:8px Cinzel,serif;letter-spacing:.1em}.run-stats b{display:block;margin-top:6px;color:var(--gold2);font:18px Cinzel,serif}.game-footer{position:absolute;z-index:3;left:5.3%;right:5.3%;bottom:22px;display:flex;gap:20px;color:#d0c0a5;font:8px Cinzel,serif;letter-spacing:.11em}.game-footer span i{font-style:normal;color:#928588;margin-left:4px}.footer-tip{margin-left:auto;color:#897d7e}.toast{position:absolute;z-index:4;top:145px;left:50%;transform:translateX(-50%);padding:9px 16px;color:#f3d9aa;border:1px solid #d9b96a58;background:#17111cdd;font:9px Cinzel,serif;letter-spacing:.16em;opacity:0;transition:opacity .25s;pointer-events:none}.toast.show{opacity:1}.mobile-controls{position:absolute;z-index:4;bottom:56px;left:5%;right:5%;justify-content:space-between;align-items:flex-end;pointer-events:none}.mobile-controls button{pointer-events:auto;border:1px solid #dbbb8060;background:#17121dbb;color:#f0d7a8;touch-action:none}.dpad>button,.dpad div button{width:39px;height:39px;border-radius:50%;font-size:13px}.dpad>button{display:block;margin:auto auto 4px}.dpad div{display:flex;gap:4px}.action-pad{display:flex;align-items:flex-end;gap:8px}.action-pad button{height:52px;min-width:62px;border-radius:50%;font:8px Cinzel,serif;letter-spacing:.08em}.action-pad #mobile-attack{width:68px;height:68px;background:#9b563d9c}.mobile-controls{display:none}@keyframes fade{from{opacity:0}to{opacity:1}}
@media(max-width:850px){.intro-copy{left:6%;top:14%;width:40%}.intro-copy h1{font-size:clamp(38px,7vw,60px)}.weapon-section{left:51%;right:5%;top:24%}.weapon-card{height:210px;padding:10px 8px}.weapon-desc{font-size:8px}.weapon-name{font-size:9px}.topbar{padding:0 5%}.screen-foot{left:5%;right:5%}}
@media(max-width:620px){#game-shell{min-height:560px}.topbar{height:60px}.brand b{font-size:11px}.room-label{font-size:8px;letter-spacing:.12em}.screen{background:linear-gradient(180deg,rgba(13,10,18,.83),rgba(15,11,19,.8))}.intro-copy{left:7%;top:11%;width:86%}.intro-copy h1{font-size:42px;margin:13px 0 8px}.intro-copy p{font-size:11px;margin:0}.controls-note{margin-top:11px;font-size:7px}.weapon-section{left:7%;right:7%;top:auto;bottom:16%;max-width:none}.select-heading{font-size:8px;margin-bottom:9px}.weapon-grid{gap:7px}.weapon-card{height:181px;padding:8px 7px}.weapon-art{height:60px;font-size:43px}.bow-art{font-size:52px}.weapon-name{font-size:7.7px;letter-spacing:.05em}.weapon-desc{font-size:7px;white-space:normal;height:20px}.weapon-stats{margin-top:8px;gap:2px 4px}.weapon-stats small{font-size:6px}.weapon-pick{font-size:6px;right:7px;bottom:7px}.weapon-index{right:7px;top:8px;font-size:8px}.weapon-section>.begin-btn{height:40px;margin-top:9px}.screen-foot{bottom:12px;font-size:6px;letter-spacing:.09em}.screen-foot span:nth-child(2){display:none}.hud{top:73px;left:5%;right:5%}.health-wrap{width:135px}.health-head{font-size:8px}.wave-wrap{top:34px;min-width:130px}.wave-wrap strong{font-size:20px}.wave-wrap span,.wave-wrap small{font-size:7px}.boon-tag small{font-size:6px}.boon-tag b{font-size:8px}.boon-tag>span{font-size:17px}.dash-pips{margin-top:8px}.dash-pips i{width:12px}.game-footer{display:none!important}.mobile-controls{display:flex}.mobile-controls.hidden{display:none!important}.toast{top:135px;font-size:8px}.modal-card{padding:30px 24px}.modal-card h2{font-size:39px}}
@media(max-height:650px) and (min-width:621px){.intro-copy{top:14%}.weapon-section{top:19%}.weapon-card{height:195px}.weapon-art{height:67px}.screen-foot{bottom:12px}.game-footer{bottom:12px}}

(()=>{
'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const state={mode:'menu',weapon:'spear',keys:new Set(),mouse:{x:0,y:0,active:false},last:0,time:0,room:1,kills:0,toastTimer:0,shake:0,muted:true};
let W=0,H=0,DPR=1,scale=1,ox=0,oy=0;
const player={x:0,y:0,r:14,hp:100,max:100,speed:210,angle:-Math.PI/2,attack:0,dash:0,dashCd:0,invuln:0,walk:0,trail:[]};
let enemies=[],shots=[],particles=[],rings=[],decor=[],spawnQueue=0,spawnTimer=0,transition=0,aimPoint=null;
const roman=['I','II','III'];
const weapons={spear:{name:'Gilded Spear',cool:.43,damage:34,reach:112,range:0,wide:.65,projectile:false,color:'#f0c77e'},blades:{name:'Twin Embers',cool:.25,damage:22,reach:70,range:0,wide:1.75,projectile:false,color:'#ef8d72'},bow:{name:'Nightfall Bow',cool:.5,damage:29,reach:420,range:580,wide:.12,projectile:true,color:'#a7c7ba'}};
function resize(){DPR=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=Math.floor(W*DPR);canvas.height=Math.floor(H*DPR);canvas.style.width=W+'px';canvas.style.height=H+'px';scale=Math.min(W/1000,H/650);ox=(W-1000*scale)/2;oy=(H-650*scale)/2;ctx.setTransform(DPR,0,0,DPR,0,0)}
addEventListener('resize',resize);resize();
function world(){return {l:ox+74*scale,r:ox+926*scale,t:oy+102*scale,b:oy+573*scale}}
function toWorld(x,y){return {x:(x-ox)/scale,y:(y-oy)/scale}}
function pickWeapon(name){state.weapon=name;$$('.weapon-card').forEach(c=>{let yes=c.dataset.weapon===name;c.classList.toggle('selected',yes);c.querySelector('.weapon-pick').textContent=yes?'SELECTED':'CHOOSE'})}
$$('.weapon-card').forEach(c=>c.addEventListener('click',()=>pickWeapon(c.dataset.weapon)));
$('#begin-btn').addEventListener('click',startRun);$('#resume-btn').addEventListener('click',()=>setMode('playing'));$('#restart-btn').addEventListener('click',startRun);$('#again-btn').addEventListener('click',()=>{setMode('menu');$('#start-screen').classList.remove('hidden');$('#start-screen').classList.add('visible')});
$('#sound-btn').addEventListener('click',e=>{state.muted=!state.muted;e.currentTarget.textContent=state.muted?'♫':'♪';e.currentTarget.style.color=state.muted?'':'#f3d9aa'});
function setMode(mode){state.mode=mode;$('#start-screen').classList.add('hidden');$('#pause-screen').classList.add('hidden');$('#end-screen').classList.add('hidden');let live=mode==='playing';$('#hud').classList.toggle('hidden',!live);$('#game-footer').classList.toggle('hidden',!live);$('#mobile-controls').classList.toggle('hidden',!live)}
function startRun(){state.room=1;state.kills=0;player.hp=100;player.max=100;player.trail=[];enemies=[];shots=[];particles=[];rings=[];setMode('playing');beginRoom()}
function beginRoom(){let b=world();player.x=500;player.y=430;player.angle=-Math.PI/2;enemies=[];shots=[];spawnQueue=2+state.room*2;spawnTimer=.45;transition=1.2;$('#wave-number').textContent=roman[state.room-1]||'IV';$('#enemy-count').textContent=`${spawnQueue} WRAITHS REMAIN`;$('#boon-name').textContent=['Zephyr','Hearthfire','Moonfall'][state.room-1]||'Last Breath';$('#room-name').textContent=['THE ASHEN GALLERY','THE CINDER COURT','THE PALE SANCTUM'][state.room-1]||'THE THRONE OF DUST';toast(['THE DOORS HAVE SEALED.','THE EMBERS REMEMBER.','NO OATH GOES UNTESTED.'][state.room-1]||'THE LAST DOOR OPENS');updateHud()}
function toast(text){let el=$('#toast');el.textContent=text;el.classList.add('show');state.toastTimer=1.8}
function updateHud(){let ratio=Math.max(0,player.hp/player.max);$('#health-fill').style.width=(ratio*100)+'%';$('#health-text').textContent=`${Math.ceil(player.hp)} / ${player.max}`;$('#hearts').innerHTML=Array.from({length:5},(_,i)=>`<span style="opacity:${ratio*5>i?1:.18}"></span>`).join('');$('#dash-pips').innerHTML='<i></i><i></i>'}
function spawnEnemy(){let b={l:82,r:918,t:115,b:565};let side=Math.floor(Math.random()*4),x=side===0?b.l:side===1?b.r:Math.random()*(b.r-b.l)+b.l,y=side===2?b.t:side===3?b.b:Math.random()*(b.b-b.t)+b.t;let type=Math.random()<.25&&state.room>=2?'archer':Math.random()<.2?'brute':'wraith';let hp=type==='brute'?105:type==='archer'?50:62;enemies.push({x,y,hp,max:hp,r:type==='brute'?19:13,type,speed:type==='brute'?44:type==='archer'?48:66,attack:1+Math.random(),hit:0,phase:Math.random()*6,dead:false});spawnQueue--;updateEnemyCount()}
function updateEnemyCount(){let n=enemies.filter(e=>!e.dead).length+spawnQueue;$('#enemy-count').textContent=`${n} ${n===1?'WRAITH':'WRAITHS'} REMAIN`}
function rand(a,b){return a+Math.random()*(b-a)}
function addBurst(x,y,color,n=8,power=100){for(let i=0;i<n;i++){let a=Math.random()*Math.PI*2,s=rand(power*.25,power);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rand(.22,.6),max:.6,color,r:rand(1,3)})}}
function startAttack(x,y){if(state.mode!=='playing'||player.attack>0)return;const w=weapons[state.weapon];player.attack=w.cool;let a=Math.atan2(y-player.y,x-player.x);player.angle=a;player.walk=0;
 if(w.projectile){shots.push({x:player.x+Math.cos(a)*18,y:player.y+Math.sin(a)*18,vx:Math.cos(a)*510,vy:Math.sin(a)*510,r:4,life:1.3,damage:w.damage,team:'player',color:w.color});addBurst(player.x+Math.cos(a)*18,player.y+Math.sin(a)*18,w.color,5,45)}else{rings.push({x:player.x,y:player.y,a,life:.22,max:.22,reach:w.reach,wide:w.wide,color:w.color});addBurst(player.x+Math.cos(a)*26,player.y+Math.sin(a)*26,w.color,5,45);for(const e of enemies){if(e.dead)continue;let dx=e.x-player.x,dy=e.y-player.y,d=Math.hypot(dx,dy),diff=Math.atan2(Math.sin(Math.atan2(dy,dx)-a),Math.cos(Math.atan2(dy,dx)-a));if(d<w.reach+e.r&&Math.abs(diff)<w.wide/2){hurtEnemy(e,w.damage,a)}}}}
function hurtEnemy(e,dmg,a){e.hp-=dmg;e.hit=.12;e.x+=Math.cos(a)*10;e.y+=Math.sin(a)*10;addBurst(e.x,e.y,e.type==='brute'?'#dc9874':'#c8d0bc',8,95);if(e.hp<=0){e.dead=true;state.kills++;addBurst(e.x,e.y,'#c9b188',18,150);updateEnemyCount()}}
function doDash(){if(state.mode!=='playing'||player.dashCd>0)return;let dx=(state.keys.has('d')||state.keys.has('ArrowRight')?1:0)-(state.keys.has('a')||state.keys.has('ArrowLeft')?1:0),dy=(state.keys.has('s')||state.keys.has('ArrowDown')?1:0)-(state.keys.has('w')||state.keys.has('ArrowUp')?1:0);if(!dx&&!dy){dx=Math.cos(player.angle);dy=Math.sin(player.angle)}let l=Math.hypot(dx,dy)||1;player.dash=.19;player.dashCd=.85;player.invuln=.32;player.x+=dx/l*12;player.y+=dy/l*12;player.trail=[];addBurst(player.x,player.y,'#e7c68b',12,95)}
function pauseToggle(){if(state.mode==='playing')setMode('paused');else if(state.mode==='paused')setMode('playing')}
addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();let k=e.key.toLowerCase();state.keys.add(k);if(k===' '||k==='shift')doDash();if(k==='escape')pauseToggle();if(k==='enter'&&state.mode==='menu')startRun()});addEventListener('keyup',e=>state.keys.delete(e.key.toLowerCase()));
canvas.addEventListener('pointermove',e=>{state.mouse.x=e.clientX;state.mouse.y=e.clientY;state.mouse.active=true});canvas.addEventListener('pointerdown',e=>{if(state.mode==='playing'&&e.button===0){let p=toWorld(e.clientX,e.clientY);startAttack(p.x,p.y)}});
$('#mobile-attack').addEventListener('pointerdown',e=>{e.preventDefault();startAttack(player.x+Math.cos(player.angle)*100,player.y+Math.sin(player.angle)*100)});$('#mobile-dash').addEventListener('pointerdown',e=>{e.preventDefault();doDash()});$$('.dpad button').forEach(b=>{let k={up:'w',down:'s',left:'a',right:'d'}[b.dataset.dir];b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);state.keys.add(k)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>state.keys.delete(k))) });

function update(dt){state.time+=dt;if(state.toastTimer>0){state.toastTimer-=dt;if(state.toastTimer<=0)$('#toast').classList.remove('show')}state.shake=Math.max(0,state.shake-dt*18);if(state.mode!=='playing'){updateParticles(dt);return}if(transition>0)transition-=dt;player.attack=Math.max(0,player.attack-dt);player.dashCd=Math.max(0,player.dashCd-dt);player.invuln=Math.max(0,player.invuln-dt);player.dash=Math.max(0,player.dash-dt);let dx=(state.keys.has('d')||state.keys.has('arrowright')?1:0)-(state.keys.has('a')||state.keys.has('arrowleft')?1:0),dy=(state.keys.has('s')||state.keys.has('arrowdown')?1:0)-(state.keys.has('w')||state.keys.has('arrowup')?1:0),len=Math.hypot(dx,dy);if(len){dx/=len;dy/=len;player.angle=Math.atan2(dy,dx);player.walk+=dt*13}else if(state.mouse.active){let p=toWorld(state.mouse.x,state.mouse.y);player.angle=Math.atan2(p.y-player.y,p.x-player.x)}else if(enemies.length){let e=enemies.find(e=>!e.dead);if(e)player.angle=Math.atan2(e.y-player.y,e.x-player.x)}
