 if(spawnQueue>0){spawnTimer-=dt;if(spawnTimer<=0){spawnEnemy();spawnTimer=rand(.8,1.3)}}
 for(const e of enemies){if(e.dead)continue;e.phase+=dt*3;e.hit=Math.max(0,e.hit-dt);e.attack-=dt;let ex=player.x-e.x,ey=player.y-e.y,d=Math.hypot(ex,ey)||1;if(e.type==='archer'){if(d>260){e.x+=ex/d*e.speed*dt;e.y+=ey/d*e.speed*dt}else if(d<180){e.x-=ex/d*e.speed*.65*dt;e.y-=ey/d*e.speed*.65*dt}if(e.attack<=0&&d<430){let a=Math.atan2(ey,ex);shots.push({x:e.x,y:e.y,vx:Math.cos(a)*190,vy:Math.sin(a)*190,r:5,life:3,damage:12,team:'enemy',color:'#cf736d'});e.attack=2.2+Math.random()*.5}}else if(d>e.r+player.r+4){e.x+=ex/d*e.speed*dt;e.y+=ey/d*e.speed*dt}if(d<e.r+player.r+4&&player.invuln<=0&&e.attack<=0){player.hp=Math.max(0,player.hp-(e.type==='brute'?18:11));player.invuln=.7;e.attack=.85;state.shake=5;addBurst(player.x,player.y,'#f18172',11,115);updateHud();if(player.hp<=0)endRun(false)}}
 for(let i=shots.length-1;i>=0;i--){let s=shots[i];s.x+=s.vx*dt;s.y+=s.vy*dt;s.life-=dt;if(s.life<=0){shots.splice(i,1);continue}if(s.team==='player'){for(const e of enemies){if(!e.dead&&Math.hypot(e.x-s.x,e.y-s.y)<e.r+s.r){hurtEnemy(e,s.damage,Math.atan2(s.vy,s.vx));shots.splice(i,1);break}}}else if(Math.hypot(player.x-s.x,player.y-s.y)<player.r+s.r&&player.invuln<=0){player.hp=Math.max(0,player.hp-s.damage);player.invuln=.7;shots.splice(i,1);state.shake=4;addBurst(player.x,player.y,'#f18172',10,100);updateHud();if(player.hp<=0)endRun(false)}}
 for(let i=rings.length-1;i>=0;i--){rings[i].life-=dt;if(rings[i].life<=0)rings.splice(i,1)}updateParticles(dt);if(spawnQueue===0&&enemies.every(e=>e.dead)){if(state.room<3){transition-=dt;if(transition<=-1){state.room++;player.hp=Math.min(player.max,player.hp+22);updateHud();beginRoom()}}else endRun(true)}}
function updateParticles(dt){for(let i=particles.length-1;i>=0;i--){let p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=Math.pow(.08,dt);p.vy*=Math.pow(.08,dt);p.life-=dt;if(p.life<=0)particles.splice(i,1)}}
function endRun(won){if(state.mode==='won'||state.mode==='lost')return;state.mode=won?'won':'lost';$('#hud').classList.add('hidden');$('#game-footer').classList.add('hidden');$('#mobile-controls').classList.add('hidden');$('#end-screen').classList.remove('hidden');$('#end-eyebrow').textContent=won?'THE GALLERY FALLS SILENT':'THE UNDERHALL CLAIMS ITS DUE';$('#end-title').innerHTML=won?'OATH<br><em>FULFILLED.</em>':'OATH<br><em>UNBROKEN.</em>';$('#end-copy').textContent=won?'The Underhall remembers your name.':'Even the fallen leave an echo.';$('#stat-rooms').textContent=won?'3':String(Math.max(0,state.room-1));$('#stat-kills').textContent=state.kills}

