Index: game.js
===================================================================
--- game.js
+++ game.js
@@ -14,9 +14,9 @@
 function pickWeapon(name){state.weapon=name;$$('.weapon-card').forEach(c=>{let yes=c.dataset.weapon===name;c.classList.toggle('selected',yes);c.querySelector('.weapon-pick').textContent=yes?'SELECTED':'CHOOSE'})}
 $$('.weapon-card').forEach(c=>c.addEventListener('click',()=>pickWeapon(c.dataset.weapon)));
 $('#begin-btn').addEventListener('click',startRun);$('#resume-btn').addEventListener('click',()=>setMode('playing'));$('#restart-btn').addEventListener('click',startRun);$('#again-btn').addEventListener('click',()=>{setMode('menu');$('#start-screen').classList.remove('hidden');$('#start-screen').classList.add('visible')});
 $('#sound-btn').addEventListener('click',e=>{state.muted=!state.muted;e.currentTarget.textContent=state.muted?'♫':'♪';e.currentTarget.style.color=state.muted?'':'#f3d9aa'});
-function setMode(mode){state.mode=mode;$('#start-screen').classList.add('hidden');$('#pause-screen').classList.add('hidden');$('#end-screen').classList.add('hidden');let live=mode==='playing';$('#hud').classList.toggle('hidden',!live);$('#game-footer').classList.toggle('hidden',!live);$('#mobile-controls').classList.toggle('hidden',!live)}
+function setMode(mode){state.mode=mode;$('#start-screen').classList.add('hidden');$('#pause-screen').classList.toggle('hidden',mode!=='paused');$('#end-screen').classList.add('hidden');let live=mode==='playing';$('#hud').classList.toggle('hidden',!live);$('#game-footer').classList.toggle('hidden',!live);$('#mobile-controls').classList.toggle('hidden',!live)}
 function startRun(){state.room=1;state.kills=0;player.hp=100;player.max=100;player.trail=[];enemies=[];shots=[];particles=[];rings=[];setMode('playing');beginRoom()}
 function beginRoom(){player.x=500;player.y=430;player.angle=-Math.PI/2;enemies=[];shots=[];spawnQueue=2+state.room*2;spawnTimer=.45;transition=1.2;$('#wave-number').textContent=roman[state.room-1]||'IV';$('#enemy-count').textContent=`${spawnQueue} WRAITHS REMAIN`;$('#boon-name').textContent=['Zephyr','Hearthfire','Moonfall'][state.room-1]||'Last Breath';$('#room-name').textContent=['THE ASHEN GALLERY','THE CINDER COURT','THE PALE SANCTUM'][state.room-1]||'THE THRONE OF DUST';toast(['THE DOORS HAVE SEALED.','THE EMBERS REMEMBER.','NO OATH GOES UNTESTED.'][state.room-1]||'THE LAST DOOR OPENS');updateHud()}
 function toast(text){let el=$('#toast');el.textContent=text;el.classList.add('show');state.toastTimer=1.8}
 function updateHud(){let ratio=Math.max(0,player.hp/player.max);$('#health-fill').style.width=(ratio*100)+'%';$('#health-text').textContent=`${Math.ceil(player.hp)} / ${player.max}`;$('#hearts').innerHTML=Array.from({length:5},(_,i)=>`<span style="opacity:${ratio*5>i?1:.18}"></span>`).join('');$('#dash-pips').innerHTML='<i></i><i></i>'}
